cat > src/CheckoutPricing.Domain/ShippingFeePolicy.cs <<'EOF'
namespace CheckoutPricing.Domain;

public static class ShippingFeePolicy
{
    private const int StandardCents = 490;
    private const int ExpressCents = 990;
    private const int FreeStandardFromCents = 5_000;

    public static int FeeCents(int payableTotalCents, LoyaltyTier tier, bool express) =>
        express ? Express(tier) : Standard(payableTotalCents, tier);

    private static int Express(LoyaltyTier tier) =>
        tier == LoyaltyTier.Platinum ? 0 : ExpressCents;

    private static int Standard(int payableTotalCents, LoyaltyTier tier) =>
        tier is LoyaltyTier.Gold or LoyaltyTier.Platinum || payableTotalCents >= FreeStandardFromCents
            ? 0
            : StandardCents;
}
EOF
cat > src/CheckoutPricing.Application/CalculateShippingFee.cs <<'EOF'
using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed record CalculateShippingFeeQuery(int PayableTotalCents, LoyaltyTier LoyaltyTier, bool Express = false);

public sealed class CalculateShippingFee
{
    public int Handle(CalculateShippingFeeQuery query) =>
        ShippingFeePolicy.FeeCents(query.PayableTotalCents, query.LoyaltyTier, query.Express);
}
EOF
cat > src/CheckoutPricing.Application/QuoteCheckout.cs <<'EOF'
using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed record QuoteCheckoutQuery(int SubtotalCents, LoyaltyTier LoyaltyTier, string? PromoCode, bool Express);

public sealed record CheckoutQuote(int PayableCents, int ShippingCents, int TotalCents);

public sealed class QuoteCheckout
{
    private readonly CalculateLoyaltyDiscount discount = new();
    private readonly CalculateShippingFee shipping = new();

    public CheckoutQuote Handle(QuoteCheckoutQuery query)
    {
        var quote = discount.Handle(new CalculateLoyaltyDiscountQuery(query.SubtotalCents, query.LoyaltyTier, query.PromoCode));
        var feeCents = shipping.Handle(new CalculateShippingFeeQuery(quote.TotalCents, query.LoyaltyTier, query.Express));
        return new CheckoutQuote(quote.TotalCents, feeCents, quote.TotalCents + feeCents);
    }
}
EOF
